ExtensionYandex.LoginLeaderboard = function() {
	if(ExtensionYandex.sdk_ != null) {
		
    function initPlayer() {
        return ExtensionYandex.sdk_.getPlayer().then(_player => {
                // Игрок авторизован.
                ExtensionYandex.player_ = _player;
            });
    }
    ExtensionYandex.sdk_.isAvailableMethod("leaderboards.setLeaderboardScore").then(ready => {
      // Игрок авторизован, он может смотреть и постить результат.
      if (ready) {
        initPlayer().catch(err => {
          // выбрасывает исключение.
      });
      }
    });
			;
	}
};
