	,updateSuperWeapon: function(_timeElapsed) {
		if(this.mcSuperWeaponFlashing != null) {
			this.mcSuperWeaponFlashing.gotoFrame(this.m_currentFrameSuperWeaponFlashing);
			this.mcSuperWeaponFlashing.stop();
			this.m_currentFrameSuperWeaponFlashing++;
			if(this.m_currentFrameSuperWeaponFlashing == this.mcSuperWeaponFlashing.get_totalFrames()) {
				this.m_currentFrameSuperWeaponFlashing = 1;
				GD.get_imageAction().removeChild(this.mcSuperWeaponFlashing);
				this.mcSuperWeaponFlashing.dispose();
				this.mcSuperWeaponFlashing = null;
			}
		}
		if(this.superWeaponActive) {
			return;
		}
		if(this.m_gameMap != null && this.m_gameMap.get_squadSoldier() != null && this.superWeapon != null) {
			if(!this.superWeaponActive) {
				++this.superWeaponTime;
			}
			this.superWeapon.progress.gotoFrame(this.superWeaponProgressBar * (this.superWeaponTime / this.totalSuperWeaponTime) | 0);
			if(this.superWeaponTime >= this.totalSuperWeaponTime) {
				this.superWeaponActive = true;
				this.superWeaponFlashing = true;
				this.superWeapon.icon.set_visible(false);
				this.superWeaponTime = 0;
				this.mcSuperWeaponFlashing = GD.context.vs_mgr.createAnimation("ClassReadyEffectSuperWeapon");
				this.mcSuperWeaponFlashing.set_x(this.superWeapon.get_x());
				this.mcSuperWeaponFlashing.set_y(this.superWeapon.get_y());
				GD.get_imageAction().addChild(this.mcSuperWeaponFlashing);
			}
		}
	}
