	,checkSuperWeapon: function() {
		if(this.superWeapon == null) {
			return;
		}
		if(GameSettings.get_pause() == true) {
			return;
		}
		if(!this.superWeaponActive) {
			return;
		}
		this.m_secondNoSkill = 0;
		this.m_timerNoSkill = 0;
		if(this.m_gameMap == null) {
			return;
		}
		if(this.m_gameMap.get_gameOver()) {
			return;
		}
		if(((this.m_gameMap.get_squadSoldier()[0].soldier) instanceof enemy_TeamLeaderJeep)) {
			return;
		}
		if(GD.get_progress().get_boughtUpgrades().h["Bandaging"].bought == 1) {
			var _g = 0;
			var _g1 = this.m_gameMap.get_squadSoldier().length;
			while(_g < _g1) {
				var j = _g++;
				this.m_gameMap.get_squadSoldier()[j].soldier.addLifeSoldiers("Bandaging");
			}
		}
		if(this.mcSuperWeaponFlashing != null) {
			GD.get_imageAction().removeChild(this.mcSuperWeaponFlashing);
			this.mcSuperWeaponFlashing = null;
		}
		if(GD.get_progress().get_superWeapon() == GlobalConst.get_superWeaponAirstrike()) {
			GD.playNewSound(64);
		} else if(GD.get_progress().get_superWeapon() == GlobalConst.get_superWeaponReinforcements()) {
			GD.playNewSound(61);
		} else if(GD.get_progress().get_superWeapon() == GlobalConst.get_superWeaponHorseDash()) {
			GD.playNewSound(62);
		} else if(GD.get_progress().get_superWeapon() == GlobalConst.get_superWeaponWunderwaffe()) {
			weapons_SterlingRay.waffe_sound_id = GD.playNewSound(63);
		} else if(GD.get_progress().get_superWeapon() == GlobalConst.get_superWeaponArtileryStrike()) {
			GD.playNewSound(60);
		}
		this.superWeapon.effect.set_visible(true);
		this.superWeapon.effect.signalFinished.addSlot($bind(this,this.onFinishEffectSuperweapon));
		this.superWeapon.effect.start(0,1);
		GameSettings.set_pause(true);
	}
