	,updateMartialArts: function() {
		if(this.m_soldierAlly != null && this.m_soldierEnemy != null) {
			if(this.m_soldierAlly.get_graphicsAnim().get_currentFrame() == 10) {
				var fh = GD.get_progress();
				fh.set_martialArts(fh.get_martialArts() + 1);
				if(GD.get_progress().get_martialArts() == 30 && !this.m_finishKnifeMedal) {
					GD.unlockMedal("Martial Arts");
					this.m_finishKnifeMedal = true;
				}
				if(GD.get_progress().get_martialArts() >= 25 && !this.m_finishKnifeArm) {
					this.m_finishKnifeArm = true;
				}
				GD.get_progress().missionProgress("id_9",1);
				GD.get_progress().missionProgress("id_35",1);
				GD.get_progress().missionProgress("id_44",1);
				this.m_soldierEnemy.damageLife("knife");
				this.m_soldierEnemy = null;
				this.m_soldierAlly = null;
			}
		}
	}
