	,generateObject: function(_sizeLevel) {
		if(_sizeLevel >= GameSettings.get_maxDistance() + 150 && !this.bossPart1) {
			haxe_Log.trace("bossPart1",{ fileName : "src/generation/ObjectGeneration.hx", lineNumber : 404, className : "generation.ObjectGeneration", methodName : "generateObject"});
			var boss = new enemy_Boss1(this.m_gameMap,new openfl_geom_Point(400.,-150));
			this.bossPart1 = true;
			this.bossActive = true;
		}
		if(_sizeLevel >= GameSettings.get_maxDistance() + 1000 && !this.bossActive) {
			if(!this.bossPart2) {
				haxe_Log.trace("bossPart2",{ fileName : "src/generation/ObjectGeneration.hx", lineNumber : 412, className : "generation.ObjectGeneration", methodName : "generateObject"});
				var boss2 = new enemy_Boss2(this.m_gameMap,new openfl_geom_Point(400,-300));
				this.bossPart2 = true;
				this.bossActive = true;
			}
		}
		if(_sizeLevel >= this.stepGeneration * this.m_count && this.bossActive && this.m_gameMap.get_levelScrolling().get_scroll()) {
			if(this.bossPart1 && !this.bossPart2) {
				this.generateProc(JsonLoader.settingJsonBoss1Mode);
			}
			if(this.bossPart1 && this.bossPart2) {
				this.generateProc(JsonLoader.settingJsonBoss2Mode);
			}
			this.m_count++;
		}
		if(_sizeLevel >= this.stepGeneration * this.m_count && _sizeLevel < GameSettings.get_maxDistance() && this.bossActive == false) {
			if(this.get_currentIndex() < this.jsonLoader.get_arrayObject().length - 1) {
				if(_sizeLevel > this.jsonLoader.get_arrayObject()[this.get_currentIndex()].checkPoint) {
					this.set_currentIndex(this.get_currentIndex() + 1);
				}
			}
			this.generateProc(this.jsonLoader.get_arrayObject()[this.get_currentIndex()]);
			this.m_count++;
		}
	}
