	,Resize: function() {
		var resize_data = GameApp.resize_dt();
		this.gm_ctx_.root.set_x(resize_data.scroll_x + resize_data.offset_x);
		this.gm_ctx_.root.set_y(resize_data.offset_y);
		this.gm_ctx_.root.set_scaleY(this.gm_ctx_.root.set_scaleX(resize_data.scale));
		this.missionCont_.set_y(resize_data.height * 0.5);
		this.missionContBtn_.set_y(this.missionContSkill_.set_y(this.missionContWeapon_.set_y(this.missionCont_.get_y())));
		this.btn_play_.set_x(resize_data.width - this.btn_play_.get_width() / 2 - 20 - 10);
		this.btn_upgrades_.set_x(this.btn_play_.get_width() / 2 + 10 + 10);
		this.btn_upgrades_.set_y(resize_data.height - 70 - 10);
		this.btn_play_.set_y(resize_data.height - 75 - 10 - 20);
		this.button_cancel_.set_x(resize_data.width / 2);
		this.button_cancel_.set_y(this.btn_upgrades_.get_y() - 50);
		var soundBarCont = iriysoft_helper_Fwh.GetByNameC(this.scr_,"soundBarCont");
		soundBarCont.set_x(resize_data.width - 150);
		if(this.jel != null) {
			this.jel.set_x(this.btn_upgrades_.get_x() + 55);
			this.jel.set_y(this.btn_upgrades_.get_y() - 55);
		}
		this.start_bg.set_y(resize_data.height - 750);
		if(this.gm_ctx_.vs_mgr.fontQualityScale() != resize_data.font_scale) {
			this.gm_ctx_.vs_mgr.setFontQualityScale(resize_data.font_scale);
		}
	}
