	,initHitTest: function() {
		var h = DictionaryUpgrades.get_UPGRADES().h;
		var _g_h = h;
		var _g_keys = Object.keys(h);
		var _g_length = _g_keys.length;
		var _g_current = 0;
		while(_g_current < _g_length) {
			var key = _g_keys[_g_current++];
			var _g1_key = key;
			var _g1_value = _g_h[key];
			var id = _g1_key;
			var value = _g1_value;
			var hit = iriysoft_helper_Fwh.GetByPathA(this.scr_,["bg","but_mcBadge" + id]);
			if(hit != null) {
				hit.touchable = true;
				hit.signalTouch.removeAllSlots();
				hit.signalTouch.addSlot($bind(this,this.clickOnBadgeMobile));
			}
		}
	}
	,rollOutBadge: function() {
		if(this.iconBase_.get_visible()) {
			iriysoft_helper_Fwh.GetByPathA(this.scr_,["bg","mcBadge" + this.iconBaseName]).set_visible(true);
			this.iconBase_.set_visible(false);
		}
		if(this.hint_ != null) {
			this.hint_.dispose();
			this.hint_ = null;
		}
		if(this.hint_select_ != null) {
			this.hint_select_.dispose();
			this.hint_select_ = null;
		}
	}
	,iconBaseShow: function(nameBadge) {
		this.iconBaseName = nameBadge;
		var budge = DictionaryUpgrades.get_UPGRADES().h[this.iconBaseName];
		if(budge.rank > this.m_rank) {
			return;
		}
		GD.playNewSound(1);
		if(budge.price > GD.get_progress().get_money()) {
			return;
		}
		if(GD.get_progress().get_boughtUpgrades().h[this.iconBaseName].bought != 0) {
			return;
		}
		this.iconBase_.set_visible(true);
	}
	,rollOnBadge: function(view) {
		this.rollOutBadge();
		var nameBadges = HxOverrides.substr(view.get_name(),11,null);
		this.iconBaseShow(nameBadges);
		var budge = DictionaryUpgrades.get_UPGRADES().h[nameBadges];
		if(budge.rank > this.m_rank) {
			return;
		}
		this.gm_ctx_.confirmNameTxt = text_TextRes.Get(budge.name);
		this.gm_ctx_.confirmTxt = text_TextRes.Get(budge.hint);
		var selectState = 10;
		var selectSort = 1;
		if(nameBadges.indexOf("SuperWeapon") != -1) {
			if(GD.get_progress().get_boughtUpgrades().h[nameBadges].bought == 1) {
				selectState = 13;
				selectSort = -2;
			} else if(budge.price > GD.get_progress().get_money()) {
				selectState = 17;
			} else {
				selectState = 14;
			}
		} else if(nameBadges.indexOf("Weapon") != -1 && nameBadges.indexOf("Weapon_Training") == -1) {
			if(GD.get_progress().get_boughtUpgrades().h[nameBadges].bought == 1) {
				selectState = 11;
				selectSort = -2;
			} else if(budge.price > GD.get_progress().get_money()) {
				selectState = 16;
			} else {
				selectState = 12;
			}
		} else if(GD.get_progress().get_boughtUpgrades().h[nameBadges].bought == 1) {
			selectState = 9;
			selectSort = -2;
		} else if(GD.get_progress().get_boughtUpgrades().h[nameBadges].bought == -1) {
			selectState = 10;
			selectSort = 0;
			this.gm_ctx_.confirmNameTxt = "Furrer";
			this.gm_ctx_.confirmTxt = "CAPUT!!!";
		} else if(budge.price > GD.get_progress().get_money()) {
			selectState = 15;
		}
		this.hint_ = new ui_ClassHint(this.gm_ctx_);
		this.hint_.set_x(view.get_x());
		view.get_parent().addChild(this.hint_);
		this.hint_select_ = this.gm_ctx_.vs_mgr.createAnimation("btnBG" + selectState);
		this.hint_select_.set_x(view.get_x());
		this.hint_select_.set_y(view.get_y());
		if(selectSort == 0) {
			this.button_train_.gotoFrame(2);
			this.hint_select_.set_visible(false);
		} else {
			this.button_train_.gotoFrame(1);
		}
		this.button_train_.stop();
		this.iconBase_.set_x(view.get_x());
		this.iconBase_.set_y(view.get_y() + 35);
		view.get_parent().addChild(this.iconBase_);
		this.hint_select_.set_scaleX(this.hint_select_.set_scaleY(view.get_scaleX()));
		view.get_parent().addChildAt(this.hint_select_,view.get_parent().getChildIndex(view) - selectSort);
		if(this.hint_.get_x() - this.hint_.get_width() / 2 < 0) {
			var fh = this.hint_;
			fh.set_x(fh.get_x() - (this.hint_.get_x() - this.hint_.get_width() / 2));
		}
		if(this.hint_.get_x() + this.hint_.get_width() / 2 > GameApp.resize_dt().width) {
			this.hint_.set_x(GameApp.resize_dt().width - this.hint_.get_width() / 2 - 10);
		}
		if(budge.rank == 1) {
			this.hint_.set_y(view.get_y() - 5 - iriysoft_helper_Fwh.GetByNameV(this.hint_,"hint_back").get_height());
		} else {
			this.hint_.set_y(view.get_y() + view.get_height() + 30);
		}
	}
	,clickOnBadgeMobile: function(view,_x,_y,_id) {
		if(this.body_drag_distance_ > 9) {
			this.body_drag_distance_ = 0;
			this.nameBadgeCurrent = "";
			return;
		}
		var nameBadges = HxOverrides.substr(view.get_name(),11,null);
		if(nameBadges != this.nameBadgeCurrent) {
			this.nameBadgeCurrent = nameBadges;
			this.rollOnBadge(view);
		} else {
			if(DictionaryUpgrades.getUpgradeRank(nameBadges) <= this.m_rank) {
				if(GD.get_progress().get_boughtUpgrades().h[nameBadges].bought == 0) {
					if(DictionaryUpgrades.getUpgradePrice(nameBadges) <= GD.get_progress().get_money()) {
						this.rollOutBadge();
						this.OnBuyUpgrade(null);
					} else {
						this.rollOutBadge();
					}
				} else {
					this.rollOutBadge();
				}
			} else {
				this.rollOutBadge();
			}
			this.nameBadgeCurrent = "";
		}
	}
	,buyUpgrade: function(nameBadges) {
		if(DictionaryUpgrades.getUpgradeRank(nameBadges) <= this.m_rank) {
			if(GD.get_progress().get_boughtUpgrades().h[nameBadges].bought == 1) {
				return;
			}
			if(DictionaryUpgrades.getUpgradePrice(nameBadges) <= GD.get_progress().get_money()) {
				GD.get_progress().get_boughtUpgrades().h[nameBadges].bought = 1;
				var fh = GD.get_progress();
				fh.set_money(fh.get_money() - DictionaryUpgrades.getUpgradePrice(nameBadges));
				GD.playNewSound(4);
				if(nameBadges == "SuperWeapon_ArtileryStrike") {
					GD.get_progress().set_superWeapon(GlobalConst.get_superWeaponArtileryStrike());
				}
				if(nameBadges == "SuperWeapon_Wunderwaffe") {
					GD.get_progress().set_superWeapon(GlobalConst.get_superWeaponWunderwaffe());
				}
				if(nameBadges == "SuperWeapon_HorseDash") {
					GD.get_progress().set_superWeapon(GlobalConst.get_superWeaponHorseDash());
				}
				if(nameBadges == "SuperWeapon_Reinforcements") {
					GD.get_progress().set_superWeapon(GlobalConst.get_superWeaponReinforcements());
				}
				if(nameBadges == "SuperWeapon_Airstrike") {
					GD.get_progress().set_superWeapon(GlobalConst.get_superWeaponAirstrike());
				}
				if(nameBadges == "Weapon_Rifle") {
					GD.get_progress().set_weaponTeamLeader(GlobalConst.get_weaponTeamLeaderRifle());
				}
				if(nameBadges == "Weapon_Shotgun") {
					GD.get_progress().set_weaponTeamLeader(GlobalConst.get_weaponTeamLeaderShotgun());
				}
				if(nameBadges == "Weapon_MachineGun") {
					GD.get_progress().set_weaponTeamLeader(GlobalConst.get_weaponTeamLeaderMachineGun());
				}
				if(nameBadges == "Weapon_Sterling") {
					GD.get_progress().set_weaponTeamLeader(GlobalConst.get_weaponTeamLeaderGunOfSterling());
				}
				if(nameBadges == "Weapon_RocketLauncher") {
					GD.get_progress().set_weaponTeamLeader(GlobalConst.get_weaponTeamLeaderRocketLauncher());
				}
				GD.saveProgress();
				this.initMoney();
				this.initBadges(false);
			}
		}
	}
	,clickOnBadge: function(view,_x,_y,_id) {
		var nameBadges = HxOverrides.substr(view.get_name(),11,null);
		this.rollOutBadge();
		this.buyUpgrade(nameBadges);
	}
	,initMoney: function() {
		GameApp.SetTextByName(this.moneyCont_,"moneyText",GD.get_progress().get_money() + "");
	}
	,__class__: ui_ScreenUpgradeClassScr
